117	export type SpriteUrlAuth = 'public' | 'sprite';
118	
119	/**
120	 * Set the sprite's public URL auth mode.
121	 * `public` opens the URL to anyone (the URL proxies to port 8080 / first HTTP port);
122	 * `sprite` requires org membership / a token. Needed before an embedded WebView
123	 * (e.g. ttyd) can reach a service, since the WebView can't carry the API token on
124	 * its in-page WebSocket/XHR requests.
125	 */
126	export async function updateSpriteUrlAuth(name: string, auth: SpriteUrlAuth): Promise<Sprite> {
127	  return apiRequest<Sprite>('PUT', `/sprites/${name}`, { url_settings: { auth } });
128	}
