225	export async function writeSpriteFile(
226	  spriteName: string,
227	  path: string,
228	  workingDir: string,
229	  bytes: Uint8Array,
230	  options: { mode?: string; mkdir?: boolean; contentType?: string } = {}
231	): Promise<SpriteFileWriteResult> {
232	  const token = await getToken();
233	  const params = new URLSearchParams({
234	    path,
235	    workingDir,
236	  });
237	  if (options.mode) params.set('mode', options.mode);
238	  if (options.mkdir) params.set('mkdir', 'true');
239	
240	  const body = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
241	  const response = await fetch(
242	    `${BASE_URL}/sprites/${encodeURIComponent(spriteName)}/fs/write?${params.toString()}`,
243	    {
244	      method: 'PUT',
245	      headers: {
246	        Authorization: `Bearer ${token}`,
247	        'Content-Type': options.contentType ?? 'application/octet-stream',
248	      },
249	      body: body as BodyInit,
250	    }
251	  );
252	
253	  if (response.status === 401) throw new AppError('unauthorized', 'Unauthorized');
254	  if (response.status === 404) throw new AppError('notFound', 'Not found');
255	  if (!response.ok) {
256	    const text = await response.text().catch(() => '');
257	    throw new AppError('serverError', text || `Write file error ${response.status}`, response.status);
258	  }
259	
260	  return response.json() as Promise<SpriteFileWriteResult>;
261	}
