1	import { Platform } from 'react-native';
2	import { loadToken } from './auth';
3	import { runExec } from './api';
4	
5	/**
6	 * Per-sprite account connection.
7	 *
8	 * Unlike `provision.ts` (which replays globally-saved credentials onto every new
9	 * sprite), this drives the provider CLIs' *interactive* login flows directly on a
10	 * single sprite: it runs the login command over a streaming exec TTY, parses the
11	 * verification URL / one-time code out of the output, opens the browser for the
12	 * user, forwards any pasted code back into the TTY (Claude), and watches the
13	 * sprite's credential files to detect completion.
14	 *
15	 * Three providers for now: Codex (ChatGPT), GitHub, and Claude.
16	 */
17	
18	export type ProviderId = 'codex' | 'github' | 'claude';
19	
20	export type AccountStatus = Record<ProviderId, boolean>;
21	
22	export interface ProviderMeta {
23	  id: ProviderId;
24	  label: string;
25	  /** One-line explanation shown under the provider name. */
26	  blurb: string;
27	  /** Single letter monogram shown in the status chip. */
28	  monogram: string;
29	  /** Accent color for the monogram badge. */
30	  accent: string;
31	  /** Whether the flow requires the user to paste a code back (Claude). */
32	  needsCodePaste: boolean;
33	  /** Human hint shown while waiting for the user to finish in the browser. */
34	  waitingHint: string;
35	}
36	
37	export const PROVIDERS: ProviderMeta[] = [
38	  {
39	    id: 'codex',
40	    label: 'Codex (ChatGPT)',
41	    blurb: 'Sign in with your ChatGPT account so Codex can run in this sprite.',
42	    monogram: 'C',
43	    accent: '#10A37F',
44	    needsCodePaste: false,
45	    waitingHint: 'Enter the code on the OpenAI page, then come back — this updates automatically.',
46	  },
47	  {
48	    id: 'github',
49	    label: 'GitHub',
50	    blurb: 'Authorize GitHub so this sprite can clone, pull, and push your repos.',
51	    monogram: 'G',
52	    accent: '#6E7681',
53	    needsCodePaste: false,
54	    waitingHint: 'Enter the code on the GitHub page, then come back — this updates automatically.',
55	  },
56	  {
57	    id: 'claude',
58	    label: 'Claude',
59	    blurb: 'Log in with your Claude subscription to run Claude Code in this sprite.',
60	    monogram: '✳',
61	    accent: '#D97757',
62	    needsCodePaste: true,
63	    waitingHint: 'Authorize in the browser, copy the code it shows, and paste it below.',
64	  },
65	];
66	
67	export function providerMeta(id: ProviderId): ProviderMeta {
68	  const meta = PROVIDERS.find((p) => p.id === id);
69	  if (!meta) throw new Error(`Unknown provider: ${id}`);
70	  return meta;
71	}
72	
73	// ── Detection ───────────────────────────────────────────────────────────────
74	
75	export type AccountSignatures = Record<ProviderId, string>;
76	
77	const EMPTY_SIGS: AccountSignatures = { codex: '', github: '', claude: '' };
78	
79	/**
80	 * Return a per-provider "signature" of the on-sprite credentials — the mtime and
81	 * size of the underlying file (or a marker for the env-token case), and empty
82	 * string when absent. A provider is connected iff its signature is non-empty,
83	 * and a *fresh* login is detected when the signature changes. Never throws.
84	 *
85	 * Codex writes ~/.codex/auth.json; gh writes ~/.config/gh/hosts.yml; Claude
86	 * writes ~/.claude/.credentials.json (or we store a token in ~/.sprite_env).
87	 */
88	export async function getAccountSignatures(spriteName: string): Promise<AccountSignatures> {
89	  const command = [
90	    `sig() { stat -c '%Y:%s' "$1" 2>/dev/null || true; }`,
91	    `co="$(sig "$HOME/.codex/auth.json")"`,
92	    `gh="$(sig "$HOME/.config/gh/hosts.yml")"; [ -n "$gh" ] || gh="$(sig "$HOME/.git-credentials")"`,
93	    `cl="$(sig "$HOME/.claude/.credentials.json")"; [ -n "$cl" ] || { grep -qs CLAUDE_CODE_OAUTH_TOKEN "$HOME/.sprite_env" && cl=env; }`,
