1	#!/usr/bin/env node
2	'use strict';
3	
4	/**
5	 * remote-agent — a lightweight daemon that speaks the Sprites exec + services
6	 * wire protocol so the sprites-rn-manager app can connect to any Linux machine,
7	 * not just Fly.io Sprites.
8	 *
9	 * Implements exactly the endpoints the app uses:
10	 *   PUT    /sprites/:name/services/:svc          → run a command, stream NDJSON
11	 *   GET    /sprites/:name/services/:svc/logs     → replay + stream NDJSON
12	 *   DELETE /sprites/:name/services/:svc          → kill service
13	 *   GET    /sprites/:name/exec                   → list live TTY sessions
14	 *   WS     /sprites/:name/exec?cmd=...           → new TTY session
15	 *   WS     /sprites/:name/exec/:sessionId        → attach (replays scrollback)
16	 *   POST   /sprites/:name/exec/:sessionId/kill   → kill TTY session
17	 *
18	 * The :name segment is accepted but ignored — this daemon runs on one machine.
19	 *
20	 * Usage:
21	 *   AGENT_TOKEN=<secret> PORT=8765 node index.js
22	 */
23	
24	const http = require('http');
25	const { WebSocketServer } = require('ws');
26	const pty = require('node-pty');
27	const { randomUUID } = require('crypto');
28	const { spawn } = require('child_process');
29	
30	// ---------------------------------------------------------------------------
31	// Config
32	// ---------------------------------------------------------------------------
33	
34	const PORT = parseInt(process.env.PORT || '8765', 10);
35	const TOKEN = process.env.AGENT_TOKEN;
36	
37	// How many chunks of PTY output to keep in the scrollback buffer per session.
38	// Each chunk is whatever node-pty emits in one onData call (a few hundred bytes
39	// on average), so 4000 ≈ a few hundred KB — plenty for Claude's TUI.
40	const SCROLLBACK_MAX_CHUNKS = 4000;
41	
42	// How long to keep a dead exec session in memory (for late attaches).
43	const DEAD_SESSION_TTL_MS = 5 * 60 * 1000;
44	
45	if (!TOKEN) {
46	  console.error('[remote-agent] AGENT_TOKEN is required. Set it in your environment.');
47	  process.exit(1);
48	}
49	
50	// ---------------------------------------------------------------------------
51	// In-memory stores
52	// ---------------------------------------------------------------------------
53	
54	// serviceName → { proc, events, subs, alive, exitCode }
55	const services = new Map();
56	
57	// sessionId → { pty, scrollback: Buffer[], subs: Set<WebSocket>, alive, cmd, lastActivity }
58	const execSessions = new Map();
59	
60	// ---------------------------------------------------------------------------
61	// Auth
62	// ---------------------------------------------------------------------------
63	
64	function authorized(req) {
65	  const h = req.headers.authorization || '';
66	  return h === `Bearer ${TOKEN}`;
67	}
68	
69	function rejectAuth(res) {
70	  res.writeHead(401, { 'Content-Type': 'application/json' });
71	  res.end(JSON.stringify({ error: 'Unauthorized' }));
72	}
73	
74	// ---------------------------------------------------------------------------
75	// Services helpers
76	// ---------------------------------------------------------------------------
77	
78	/**
79	 * Send a NDJSON line to a response stream.
80	 * The app's parseServiceEventLine() strips SSE "data:" prefixes and parses
81	 * each newline-terminated JSON object, so plain NDJSON (no SSE wrapping) works.
82	 */
83	function ndjsonLine(obj) {
84	  return JSON.stringify(obj) + '\n';
85	}
86	
87	function startService(res, serviceName, config) {
88	  // Stop any existing service with the same name cleanly.
89	  const existing = services.get(serviceName);
90	  if (existing) {
91	    existing.subs.clear();
92	    if (existing.proc && existing.alive) {
93	      try { existing.proc.kill('SIGTERM'); } catch {}
94	    }
95	  }
96	
97	  const events = [];
98	  const subs = new Set();
99	  const svc = { proc: null, events, subs, alive: true, exitCode: null };
100	  services.set(serviceName, svc);
101	
102	  // Schedule cleanup after a reasonable TTL so stale entries don't pile up.
103	  // Re-PUT to the same name just overwrites anyway.
104	
105	  const emit = (obj) => {
106	    events.push(obj);
107	    const line = ndjsonLine(obj);
108	    if (res && !res.writableEnded) res.write(line);
109	    for (const cb of subs) cb(line);
110	  };
111	
112	  res.writeHead(200, {
113	    'Content-Type': 'application/x-ndjson',
114	    'Transfer-Encoding': 'chunked',
115	    'Cache-Control': 'no-cache',
116	    'Connection': 'keep-alive',
117	  });
118	
119	  const cmd = config.cmd || 'bash';
120	  const args = Array.isArray(config.args) ? config.args : [];
121	
122	  emit({ type: 'started', data: `${cmd} ${args.join(' ')}`.trim() });
123	
124	  let proc;
125	  try {
126	    proc = spawn(cmd, args, {
127	      shell: false,
